      "id": "artv2850",
      "type": "course",
      "code": "ARTV2850",
      "name": "Sculpture and Spatial Practice 2",
      "college": "ANU College of Arts and Social Sciences",
      "school": "School of Art and Design",
      "schoolCode": "ARTV",
      "level": "UGRD",
