      "id": "asia9075",
      "type": "course",
      "code": "ASIA9075",
      "name": "Research Design and Writing in International, Political, and Strategic Studies",
      "college": "ANU College of Asia and the Pacific",
      "school": "Coral Bell School of Asia Pacific Affairs",
      "schoolCode": "ASIA",
      "level": "PGRD",
