      "id": "biol6204",
      "type": "course",
      "code": "BIOL6204",
      "name": "Genetics of Human Disease",
      "college": "ANU College of Science and Medicine",
      "school": "John Curtin School of Medical Research",
      "schoolCode": "JCSMR",
      "level": "PGRD",
