      "id": "clas3001",
      "type": "course",
      "code": "CLAS3001",
      "name": "Rome: The Eternal City from Antiquity to the Early Middle Ages",
      "college": "ANU College of Arts and Social Sciences",
      "school": "School of Literature, Languages and Linguistics",
      "schoolCode": "SOLLA",
      "level": "UGRD",
