      "code": "CRIM8005",
      "name": "Advanced Criminological Theory",
      "college": "ANU College of Arts and Social Sciences",
      "school": "POLIS: The Centre for Social Policy Research",
      "schoolCode": "PTCFS",
      "level": "PGRD",
