      "id": "envs3015",
      "type": "course",
      "code": "ENVS3015",
      "name": "Essentials of Environmental Law",
      "college": "ANU College of Systems and Society",
      "school": "Fenner School of Environment and Society",
      "schoolCode": "FENS",
      "level": "UGRD",
