      "id": "humn2000",
      "type": "course",
      "code": "HUMN2000",
      "name": "Introduction to Heritage and Museum Studies",
      "college": "ANU College of Arts and Social Sciences",
      "school": "Research School of Humanities and the Arts",
      "schoolCode": "HUMN",
      "level": "UGRD",
      "terms": [],
