      "id": "humn2051",
      "type": "course",
      "code": "HUMN2051",
      "name": "Introduction to Cultural Heritage Management",
      "college": "ANU College of Arts and Social Sciences",
      "school": "Research School of Humanities and the Arts",
      "schoolCode": "HUMN",
      "level": "UGRD",
