      "id": "humn8036",
      "type": "course",
      "code": "HUMN8036",
      "name": "Restitution and the archive? Using Archives and Special Collections",
      "college": "ANU College of Arts and Social Sciences",
      "school": "Research School of Humanities and the Arts",
      "schoolCode": "HUMN",
      "level": "PGRD",
