      "type": "course",
      "code": "IDEC8088",
      "name": "Cost-Benefit Analysis: Principles and Practice",
      "college": "ANU College of Law, Governance and Policy",
      "school": "Crawford School of Public Policy",
      "schoolCode": "CRAW",
