      "id": "laws4304",
      "type": "course",
      "code": "LAWS4304",
      "name": "Prison Legal Clinic",
      "college": "ANU College of Law, Governance and Policy",
      "school": "ANU Law School",
      "schoolCode": "LAW",
      "level": "UGRD",
