      "type": "course",
      "code": "LAWS8102",
      "name": "Blockchain and Legal Innovation II",
      "college": "ANU College of Law, Governance and Policy",
      "school": "ANU Law School",
      "schoolCode": "LAW",
      "level": "PGRD",
