      "id": "meas8112",
      "type": "course",
      "code": "MEAS8112",
      "name": "Dynamics of Israeli-Palestinian Conflict",
      "college": "ANU College of Arts and Social Sciences",
      "school": "Centre for Arab and Islamic Studies",
      "schoolCode": "CFAAI",
      "level": "PGRD",
