      "type": "course",
      "code": "PHYS6103",
      "name": "Advanced Statistical Mechanics",
      "college": "ANU College of Science and Medicine",
      "school": "Research School of Physics",
      "schoolCode": "PHYS",
      "level": "PGRD",
